-- ── CLEANUP AND RESET ──────────────────────────────────────────
TRUNCATE TABLE users CASCADE;

-- ── SEED ROLES ──────────────────────────────────────────────────
SELECT setval('roles_id_seq', COALESCE((SELECT MAX(id) FROM roles), 1));

-- ── SEED USERS, SETTINGS, AND PRESENCE (100 RECORDS) ──────────────




































































































SELECT setval('users_id_seq', 100);
SELECT setval('user_settings_id_seq', 100);
SELECT setval('user_presences_id_seq', 100);

-- ── SEED POSTS (50 RECORDS) ───────────────────────────────────────


















































SELECT setval('posts_id_seq', 50);

-- ── SEED PRIVATE CHATS & MESSAGES ───────────────────────────────




















SELECT setval('chats_id_seq', 20);

-- ── SEED GROUP CHATS & MESSAGES ──────────────────────────────────





SELECT setval('chats_id_seq', 25);

COMMIT;